# W7 — Temporal Data Engineering
W="W7"
add(W,"基础","Temporal data","时间数据","带有时刻、日期或有效时间段的数据。","描述事实何时发生、何时有效或数据库何时知道它。","是 temporal database 与 time series 的共同上位概念。","天气观测包含 obsdate；员工职位包含有效起止日期。")
add(W,"基础","Historical data / Long data","历史数据／长时间跨度数据","长期保存的过去记录，而不只是当前快照。","用于趋势、审计和回溯分析。","Big data 强调体量、速度、种类；long data 强调时间跨度。","比较企业过去 20 年的销售变化。")
add(W,"数据库","Temporal DBMS","时间数据库管理系统","内建时间维度支持的 DBMS，可按时间存储、查询和更新。","直接表达过去、现在、未来及时间推理，减少应用层手写逻辑。","普通 DBMS 通常只保存当前快照；temporal DBMS 提供 temporal SQL。","查询某员工在 2025-03-01 的职位。")
add(W,"数据库","Conventional database","传统／非时间数据库","主要表示现实世界当前状态的数据库。","适合当前值事务，但历史通常需应用自行维护。","与 temporal database 对比。","UPDATE 职位后旧职位被覆盖。")
add(W,"时间类型","Instant / Point","时刻／时间点","时间轴上的单一位置。","给事件或观测加精确时间标记。","与 interval 的长度、period 的有界区间不同。","2026-10-23 09:30:00。")
add(W,"时间类型","Interval","时间间隔／时长","只有长度、没有固定时间轴位置的持续量。","进行时间加减或表示持续时间。","INTERVAL '2 hours' 是时长；period 有具体起止。","timestamp + INTERVAL '30 minutes'。")
add(W,"时间类型","Period","时间段","由同类型的开始和结束边界确定的锚定区间。","表示事实在现实中的有效范围。","通常采用半开区间 [start,end)。","合同从 1 月 1 日有效到 2 月 1 日前。")
add(W,"时间类型","DATE","日期类型","只表示年、月、日，不含一天内时间。","存生日、账期日期等日粒度事实。","比 TIMESTAMP 粒度低；与 TIME 组合可形成完整时间点。","DATE '2026-10-23'。")
add(W,"时间类型","TIME","时钟时间类型","表示时、分、秒但通常没有日期。","表示每天的时间或班次时刻。","单独 TIME 不能唯一定位跨日期的事件。","TIME '17:00:00'。")
add(W,"时间类型","TIMESTAMP","时间戳","日期与时钟时间的组合，可带小数秒和时区语义。","给事件排序、过滤和连接。","TIMESTAMP WITH TIME ZONE 与无时区版本语义不同。","TIMESTAMP '2026-10-23 17:00:00'。")
add(W,"时间类型","Time zone","时区","把本地时钟时间映射到全球统一时间轴的规则。","避免跨地区记录比较错误。","时区不同于 UTC offset；夏令时会改变 offset。","悉尼 17:00 转为 UTC 后再比较纽约事件。")
add(W,"时间类型","Temporal granularity / Resolution","时间粒度／分辨率","时间值能区分的最小单位，如日、秒、毫秒。","决定能否区分相邻事件和窗口边界。","粒度过粗可能产生并列 timestamp。","日粒度不能区分同一天两笔交易的先后。")
add(W,"时间语义","User-defined time","用户定义时间","数据库不解释其时间语义的普通日期／时间属性。","由应用决定字段意义。","不同于 DBMS 认识的 valid time 或 transaction time。","birthdate 只是普通 DATE 列。")
add(W,"时间语义","Valid time / Fact time / Application time","有效时间／事实时间／应用时间","事实在现实世界中为真的时间。","回答“现实中什么时候成立”。","可被追溯修正；SQL:2011 称 application time。","合同 1 月生效，即使 2 月才录入。")
add(W,"时间语义","Transaction time / Database time / System time","事务时间／数据库时间／系统时间","某版本何时被数据库保存和可见。","支持审计、回滚和回答“数据库何时知道”。","只随系统时间向前；SQL:2011 称 system time。","数据库 2 月 3 日记录合同。")
add(W,"时间语义","Bitemporal","双时间","同时保存 valid time 与 transaction time。","既追踪现实变化，又追踪数据库认识的变化。","等于两条时间轴的组合。","3 月发现 1 月工资录错，可保留原录入和修正历史。")
add(W,"表类型","Temporal table","时间表","包含 DBMS 认可的时间列并支持时间语义查询的表。","自动或规范地维护历史版本。","可进一步分 valid-time、transaction-time、bitemporal。","Policy 表包含 Validity period。")
add(W,"表类型","Valid-time table","有效时间表","带有效时间维度的表。","记录现实事实在何时成立。","只含 valid time，不一定记录数据库修改历史。","职位记录带 start_date/end_date。")
add(W,"表类型","Transaction-time table","事务时间表","带数据库系统时间维度的表。","保存每个数据库版本的可见区间。","只含 transaction time，不一定知道现实有效期。","系统自动保存 UPDATE 前的旧行。")
add(W,"表类型","Nontemporal table","非时间表","没有 valid-time 或 transaction-time 维度的普通表。","保存当前状态或普通事件属性。","与 temporal table 相对。","只存当前地址的 Customer 表。")
add(W,"表类型","Semi-temporal table","半时间表","只记录当前事实从何时开始有效，例如 since。","低成本回答“当前状态持续多久”。","通常不能恢复完整历史。","Employee(city,since) 只保留现城市及开始日期。")
add(W,"边界","Half-open interval [start,end)","左闭右开区间","包含开始、不包含结束的时间段。","让相邻区间无重叠、无缝衔接。","BETWEEN 通常两端包含，可能导致边界重复。","[09:00,10:00) 与 [10:00,11:00) 不重复。")
add(W,"当前值","NOW / UC (Until Changed)","当前／直到改变","表示事实当前有效且结束时间尚未发生。","建模开放结束的当前记录。","PostgreSQL now 是事务开始时刻；开放结束常用 infinity。","现任职位有效至 infinity。")
add(W,"当前值","Max-timestamp / Infinity","最大时间戳／无穷","用极大日期或 infinity 表示开放结束。","使范围比较保持普通逻辑。","比 NULL 更容易查询，但必须约定语义。","end_date='9999-12-31' 或 'infinity'。")
add(W,"当前值","NULL","空值／未知值","SQL 中表示缺失或未知，而非普通数值。","表达未知数据。","与任何普通比较结果为 UNKNOWN，不能直接当“永远”。","end_date IS NULL，而不是 end_date > today。")
add(W,"查询语义","Current query","当前查询","只询问现在有效的数据。","回答当前库存、当前职位。","是 temporal statement 的一种；不恢复过去。","CURRENT VALIDTIME SELECT ...。")
add(W,"查询语义","Sequenced query","序列化时间查询","按每个有效时刻的时间语义执行关系运算。","得到随时间变化的答案。","与 nonsequenced 的“把时间列当普通数据”不同。","求每个时期各部门预算总额。")
add(W,"查询语义","Nonsequenced query","非序列时间查询","忽略内建时间语义，将时间属性当普通列处理。","执行跨历史版本的普通统计或筛选。","不自动对齐有效区间。","统计历史上一共出现过多少职位记录。")
add(W,"SQL","CURRENT_DATE / CURRENT_TIME","当前日期／当前时间","由数据库系统给出的当前日期或时间常量。","构造相对当前时刻的过滤。","值受 DBMS 与事务语义影响。","WHERE obsdate < CURRENT_DATE。")
add(W,"SQL","EXTRACT","时间分量提取函数","从日期或时间戳中取 YEAR、MONTH 等字段。","用于按年/月分组或过滤。","它返回分量，不会自动聚合。","EXTRACT(YEAR FROM ts)=2026。")
add(W,"SQL","INTERVAL arithmetic","时间间隔运算","用 INTERVAL 对时间点做加减。","计算截止时间和滚动范围。","不要把字符串或整数直接当带单位时长。","ts + INTERVAL '36 hours'。")
add(W,"SQL","BETWEEN","区间比较谓词","判断值是否位于两个端点之间，通常包含两端。","写简洁范围过滤。","连续时间窗口更安全地写 >= start AND < end。","x BETWEEN 1 AND 3 包含 1 和 3。")
add(W,"标准","SQL:2011 PERIOD FOR","SQL:2011 时间段定义","把物理 start/end 列声明为一个概念 period。","让 DBMS 理解 application/system time。","它是表元数据分组，并非普遍的新标量类型。","PERIOD FOR EPeriod(EStart,EEnd)。")
add(W,"分析","Temporal aggregation","时间聚合","在每个时间片上计算当时有效记录的聚合值。","产生随时间变化的 SUM/COUNT/AVG。","普通 GROUP BY 只给静态组结果；时间聚合需切分变化点。","每个时期计算部门有效项目预算。")
add(W,"PostgreSQL","Range type / DATERANGE","范围类型／日期范围","把上下界作为单个区间值保存的 PostgreSQL 类型。","直接支持包含、重叠、交并差和范围索引。","比两个独立 start/end 列更接近 period 语义。","'[2010-01-01,2011-01-01)'::daterange。")
add(W,"PostgreSQL","GiST (Generalized Search Tree)","广义搜索树索引","支持可扩展谓词的索引框架，适合范围和空间对象。","加速 overlap、contains 等不能靠普通排序键充分表达的查询。","B-tree 适合标量顺序；GiST 可索引区间关系。","CREATE INDEX ... USING gist(valid_period)。")
add(W,"PostgreSQL","Overlap operator &&","重叠运算符","判断两个 PostgreSQL range 是否有共同部分。","查时间冲突或连接同时有效记录。","条件等价思想为 a.start < b.end AND b.start < a.end。","预订区间 && 已有预订区间。")
add(W,"PostgreSQL","upper_inf()","上界无穷检查函数","判断 range 的上界是否为正无穷。","找到当前仍开放的时间段。","不同于 upper(range)，它返回布尔值。","WHERE upper_inf(valid_period)。")
add(W,"PostgreSQL","Range union / intersection / difference","范围并／交／差","对可合并范围执行 +、*、- 运算。","组合或比较有效区间。","union 通常要求范围相交或相邻。","'[2010,2013)' * '[2012,2015)' 得 [2012,2013)。")
add(W,"时间序列","Time series","时间序列","按时间先后排列的一系列观测值。","分析趋势、周期、变化和预测。","属于 temporal data，通常强调离散时间点序列。","每小时温度读数。")
add(W,"流程","Data ingress","数据进入／摄取","从文件、数据库或网页把数据引入分析流程。","建立时间序列处理的输入端。","后续还有 storage、analysis、visualisation。","读取 CSV 并解析 timestamp。")
add(W,"存储","Point-based representation","点式表示","每个观测时间点单独占一行。","便于过滤、更新、B-tree 索引和关系查询。","与一行保存数组的 sequence-based 表示对比。","(station,ts,temp) 每分钟一行。")
add(W,"存储","Sequence-based representation","序列式表示","一行保存一段有序时间点或值数组。","减少行数并对整段序列操作。","必须维护顺序、数组长度和时间值对齐。","一天一行保存 timestamps[] 与 temperatures[]。")
add(W,"关系模型","Atomic value","原子值","关系表一个单元中不可再分的单值。","满足传统关系模型的基本字段假设。","数组是复合值，因此 sequence-based 表示偏离严格 1NF。","单个 temperature=22.5。")
add(W,"关系模型","1NF (First Normal Form)","第一范式","每个属性位置保存单一原子值的关系设计原则。","让关系操作和约束保持简单一致。","数组列或嵌套表通常被视为超出严格 1NF。","把多个温度拆成多行符合 1NF。")
add(W,"数据库","Append-only","仅追加写入","主要插入新事件，不覆盖旧事件。","天然保留历史并简化审计。","与 UPDATE 当前行不同。","传感器每来一条观测就 INSERT。")
add(W,"数据库","B-tree index","B 树索引","按可排序键组织的通用索引。","加速等值和范围查询。","适合单一 timestamp；复杂 range overlap 常用 GiST。","CREATE INDEX ON observations(ts)。")
add(W,"分析","OLAP","联机分析处理","面向大量数据的筛选、分组和聚合分析。","总结时间序列和仓库数据。","与高频小事务 OLTP 侧重点不同。","按站点和月份计算 AVG(temp)。")
add(W,"建模","Dimension table","维度表","保存描述性实体属性供事实数据连接。","给观测增加站点、地区等上下文。","时间序列表常是事实表，维度表较稳定。","Observations JOIN Station ON station_id。")
add(W,"数组","Array","数组","一个字段内按位置保存多个同类型元素。","实现序列式时间数据。","顺序是语义的一部分；平行数组必须对齐。","temperature FLOAT[]。")
add(W,"数组","array_agg()","数组聚合函数","把多行值收集成一个数组。","从 point-based 转为 sequence-based。","内部 ORDER BY 才能保证数组顺序。","array_agg(temp ORDER BY ts)。")
add(W,"数组","UNNEST","数组展开操作","把一个数组的元素转换为多行。","从 sequence-based 恢复为关系行。","多个数组分别展开可能产生错配或笛卡尔扩张。","SELECT unnest(temperatures)。")
add(W,"索引","GIN (Generalized Inverted Index)","广义倒排索引","为数组、全文等多值内容建立倒排项到行的映射。","加速数组包含或元素搜索。","GiST 擅长范围/空间关系；GIN 擅长成员集合查询。","CREATE INDEX ... USING gin(tags)。")
add(W,"JSON","Schema-on-read","读时模式","数据写入时保持灵活，读取时才解释结构。","适配结构可变的 JSON。","灵活不等于无模式；查询仍依赖稳定字段含义。","读取 values[].date 时应用日期类型。")
add(W,"JSON","Data-as-field-name anti-pattern","把数据当字段名的反模式","用日期等实例值充当 JSON key。","虽然便于对象查找，却破坏范围查询和字段索引。","字段名应表达 schema，日期应作为 value。","错误：{'2026-01-01':100}；正确：{'date':'2026-01-01','sales':100}。")

# W8 — Unstructured Data
W="W8"
add(W,"数据类型","Structured data","结构化数据","遵循固定字段、类型和表模式的数据。","可直接由关系数据库存储与查询。","与 semi-structured、unstructured 构成结构程度谱系。","Customer(id,name,age) 表。")
add(W,"数据类型","Semi-structured data","半结构化数据","有键、标签或层级，但记录结构可变化的数据。","保留部分机器可读结构同时允许灵活字段。","JSON/XML 通常属于半结构化，不是纯文本式非结构化。","两个 JSON 文档可有不同可选字段。")
add(W,"数据类型","Unstructured data","非结构化数据","不能直接用固定行列完整表达内容的数据。","需要预处理和特征提取后才能被传统分析或 ML 使用。","并非完全没有内部结构。","自然语言、照片、视频。")
add(W,"文本","NLP (Natural Language Processing)","自然语言处理","让计算机分析、理解或生成自然语言的方法集合。","从文本提取语义、实体、情感或分类特征。","tokenisation 与 embedding 是常见 NLP 管线环节。","判断评论是正面还是负面。")
add(W,"文本","Semantic analysis","语义分析","分析文本表达的含义，而不仅是字符或词频。","处理歧义、关系和意图。","比单纯关键词计数更关注上下文。","bank 在河岸与银行语境中含义不同。")
add(W,"图像","Vector graphics","矢量图形","用点、线、曲线和形状的数学描述表示图像。","可无损缩放并保留对象结构。","与像素网格 raster image 对比。","SVG 徽标放大后仍清晰。")
add(W,"图像","Raster image","栅格图像","由固定行列像素矩阵组成的图像。","适合照片和逐像素处理。","分辨率固定，放大会显像素。","JPEG 照片。")
add(W,"图像","Pixel","像素","栅格图像中最小的采样元素。","保存某位置的亮度或颜色值。","多个 channel 共同描述一个彩色像素。","RGB 像素 (255,0,0) 为红色。")
add(W,"图像","Channel","通道","图像中一种颜色或测量维度的二维矩阵。","分别保存红、绿、蓝或其他信号。","RGB 有 3 个通道；灰度通常 1 个。","green channel 可突出某类血管信号。")
add(W,"图像","Bit depth / bpp","位深／每像素位数","用于表示像素或通道的比特数量。","决定可表示的强度或颜色级数。","位深越高级数越多，同时存储量通常更大。","8 bit 可表示 2^8=256 个值。")
add(W,"图像","RGB / TrueColor","RGB 真彩色","用红、绿、蓝三个通道组合颜色的图像。","表达常见彩色照片。","典型真彩色为每通道 8 bit，总计 24 bpp。","(255,255,0) 组合为黄色。")
add(W,"图像","Grayscale image","灰度图","每个像素只保存一个明暗值的单通道图像。","降低计算量并突出强度结构。","不是 binary image；可有许多灰度级。","8-bit 灰度 CT 切片。")
add(W,"图像","Binary image / Mask","二值图／掩膜","像素只有 0/1 或黑/白两类。","标记目标区域、前景或有效位置。","常由 thresholding 或 segmentation 产生。","血管区域为 1，背景为 0。")
add(W,"图像","Image feature","图像特征","从图像提取的可比较数值描述。","把视觉内容转换为分类、检索或分析可用的向量。","可由手工 descriptor 或神经网络学习。","边缘方向直方图。")
add(W,"图像","Classical computer vision","传统计算机视觉","使用人工设计的滤波器、边缘、关键点等算法分析图像。","提供可解释的 white-box 特征。","与深度视觉自动学习 representation 对比。","用 Sobel 算子提取边缘。")
add(W,"图像","Deep computer vision","深度计算机视觉","用深度神经网络从数据学习图像表示。","减少手工特征设计并处理复杂语义。","常见模型包括 CNN 和 Vision Transformer。","模型学习“猫”的 embedding。")
add(W,"图像","CNN (Convolutional Neural Network)","卷积神经网络","利用局部卷积核逐层学习空间模式的网络。","从边缘到形状再到对象构建层次特征。","是深度图像特征提取方法。","用预训练 CNN 为商品图片生成向量。")
add(W,"图像","Vision Transformer (ViT)","视觉 Transformer","把图像切成 patch 并用 Transformer 建模其关系。","学习全局图像表示。","与 CNN 的局部卷积归纳偏置不同。","将 16×16 patch 序列输入 ViT。")
add(W,"图像","Multimodal foundation model","多模态基础模型","同时处理文本、图像等多种模态的大规模预训练模型。","连接文字描述和视觉内容。","可用共享 embedding 支持图文检索。","用文字“红色汽车”搜索图片。")
add(W,"机器学习","Feature extraction","特征提取","把原始文本或图像转换为数值特征。","让 ML 算法能够接收非结构化数据。","位于 preprocessing 后、model training 前。","把邮件转换为 TF-IDF 向量。")
add(W,"机器学习","Embedding","嵌入向量","在连续向量空间中表示词、文档、图像或实体。","让语义相近对象在空间中距离更近。","dense embedding 与 sparse TF-IDF 不同。","两个同义句的向量 cosine 较高。")
add(W,"机器学习","Derived data product","派生数据产品","由原始数据计算出的可复用结果，如特征或 embedding。","需要版本、质量、血缘和存储管理。","不是临时中间值；它也属于数据工程资产。","保存图片 embedding 供搜索服务使用。")
add(W,"机器学习","Supervised learning","监督学习","使用带正确答案 label 的训练数据学习映射。","做分类或回归预测。","与无标签的 unsupervised learning 对比。","用标注 spam/not-spam 邮件训练分类器。")
add(W,"机器学习","Ground truth / Label","真实标签／标注","训练或评估时作为正确答案的目标值。","指导监督模型并衡量预测误差。","标签质量直接限制模型质量。","邮件人工标为 spam=1。")
add(W,"机器学习","Classification","分类","预测离散类别的监督学习任务。","决定对象属于哪个类别。","离散输出；regression 输出连续数值。","预测图片是猫还是狗。")
add(W,"机器学习","Regression","回归","预测连续数值的监督学习任务。","估计价格、温度等数量。","不要因使用“回归模型”就把离散标签当连续目标。","预测房价 850000。")
add(W,"机器学习","Unsupervised learning","无监督学习","在没有 label 的数据中寻找结构或分布。","用于聚类、降维和异常发现。","不能直接用“准确率”对照未知标签。","按 embedding 将新闻自动分组。")
add(W,"机器学习","Clustering","聚类","按相似性把未标注对象分成组。","发现潜在群体结构。","是无监督学习典型任务。","把客户按购买行为分群。")
add(W,"机器学习","Train/test split","训练／测试集划分","将数据分为拟合模型和最终评估的互斥集合。","估计模型对未见数据的泛化能力。","预处理器也必须只在训练集 fit。","80% 训练、20% 测试。")
add(W,"机器学习","Data leakage","数据泄漏","训练过程使用了预测时不可获得或测试集的信息。","识别并防止虚高评估。","时间序列尤其不能使用未来值。","在划分前用全体数据均值标准化。")
add(W,"文本特征","Tokenisation","分词／标记化","把文本拆成 token 单元。","建立词表、计数或送入语言模型。","token 不一定等于完整单词。","“data-driven”可被拆成多个 token。")
add(W,"文本特征","Normalisation","文本规范化","统一大小写、字符形式等表面差异。","减少相同内容产生多个特征。","过度规范化可能删除任务信号。","将 Data 和 data 都转为 data。")
add(W,"文本特征","Stemming","词干提取","用规则截断词尾得到近似词干。","合并词形并缩小词表。","可能产生非真实单词；lemmatisation 更语言学化。","connected、connecting → connect。")
add(W,"文本特征","Lemmatisation","词形还原","依据词性和词典把词变为规范词元。","更准确地合并变形。","通常比 stemming 计算更复杂。","was → be。")
add(W,"文本特征","Stop words","停用词","频繁出现且常被认为信息量低的词。","可减少维度和噪声。","不能机械删除；not 对情感非常重要。","the、a 常是停用词。")
add(W,"文本特征","Bag of Words (BoW)","词袋模型","忽略词序，只记录词出现情况或次数。","把文档转换为固定长度稀疏向量。","简单可解释，但丢失语序和上下文。","“dog bites man”与“man bites dog”词袋相同。")
add(W,"文本特征","Term Frequency (TF)","词频","词在一个文档中的出现次数或规范化频率。","衡量词对该文档的局部重要性。","TF-IDF 还会乘 inverse document frequency。","某词在文档出现 4 次，TF 可为 4。")
add(W,"文本特征","IDF (Inverse Document Frequency)","逆文档频率","根据词出现在多少文档中降低常见词权重。","突出能区分少数文档的词。","df 越大，IDF 越小。","只在少量文档出现的 database 权重较高。")
add(W,"文本特征","TF-IDF","词频—逆文档频率","用 TF×IDF 衡量词对某文档的区分性。","构建可用于分类和检索的稀疏表示。","高值表示在该文档常见但全语料不普遍。","tfidf(t,d)=tf(t,d)×log(N/df(t))。")
add(W,"文本特征","Sparse vector / Sparse matrix","稀疏向量／矩阵","绝大多数元素为 0 的表示。","节省高维词表特征的存储与计算。","BoW/TF-IDF 常稀疏；neural embedding 通常 dense。","10 万词词表中一封邮件只出现 80 个词。")
add(W,"文本特征","Vector Space Model","向量空间模型","用特征向量表示文档，并以几何关系比较。","把文本搜索转为距离或相似度计算。","与 cosine similarity 配合常见。","查询向量与文档向量比较夹角。")
add(W,"文本特征","Cosine similarity","余弦相似度","向量点积除以长度乘积，衡量方向相似度。","比较长度不同的文本向量。","值越大越相似；cosine distance 方向相反。","[1,1] 与 [2,2] 的 cosine 为 1。")
add(W,"文本特征","CountVectorizer","计数向量器","scikit-learn 中学习词表并输出 token 计数矩阵的工具。","自动完成常用 tokenisation 和 BoW 转换。","必须在训练集 fit，再对测试集 transform。","CountVectorizer(ngram_range=(1,2))。")
add(W,"文本特征","N-gram / Bigram","N 元语法／二元词组","由连续 N 个 token 组成的特征。","保留有限局部词序。","维度比 unigram 更高。","bigram “New York”。")
add(W,"语言模型","Word2Vec","词向量模型","根据词的上下文学习相对固定的 dense word embedding。","捕捉词语相似关系。","通常每个词一个向量；BERT 根据句子上下文改变表示。","king 与 queen 向量接近。")
add(W,"语言模型","GloVe","全局词向量模型","利用语料全局词共现统计学习静态词向量。","生成可复用 dense embedding。","与 Word2Vec 都偏静态；训练思想不同。","用预训练 GloVe 初始化文本模型。")
add(W,"语言模型","BERT","双向编码器 Transformer","利用左右文共同生成上下文化表示的 encoder-only 预训练模型。","适合文本理解、分类、NER，可 fine-tune。","与自回归生成型 GPT 侧重点不同。","bank 在不同句子中得到不同向量。")
add(W,"语言模型","GPT","生成式预训练 Transformer","按前文预测下一个 token 的自回归 decoder 型模型。","擅长生成和续写，也可完成多种语言任务。","BERT 双向编码理解；GPT 因果方向生成。","给定问题逐 token 生成回答。")
add(W,"语言模型","Fine-tuning","微调","在预训练模型上用特定任务数据继续训练。","让通用表示适应分类、NER 等目标。","不同于从零训练。","用标注邮件微调 BERT 做 spam 分类。")
add(W,"文本任务","Named Entity Recognition (NER)","命名实体识别","识别人名、组织、地点等实体及类别。","把非结构化文本转为结构化实体字段。","属于 NLP 信息抽取。","从新闻中提取 “University of Sydney”。")
add(W,"图像特征","ROI (Region of Interest)","感兴趣区域","图像中需要重点分析的区域。","减少无关背景并产生局部测量。","可由人工框选、segmentation 或 detector 得到。","只分析医学图像中的血管区域。")
add(W,"图像特征","Image descriptor","图像描述子","人工算法生成的局部或全局特征向量。","支持可解释的匹配与检索。","属于 white-box feature extraction。","SIFT 风格关键点描述子。")
add(W,"图像特征","Image gradient","图像梯度","像素强度或颜色在空间中的变化率。","检测边缘、方向和纹理。","许多传统 descriptor 以梯度为基础。","物体边界处梯度较大。")
add(W,"图像特征","Edge / Keypoint / Segmentation","边缘／关键点／分割","边缘标变化；关键点标稳定局部位置；分割给像素分区域。","分别支持轮廓、匹配和区域级分析。","三者粒度和输出不同。","分割输出每个像素的类别 mask。")
add(W,"图像特征","White-box vs Black-box","白盒与黑盒方法","白盒规则明确可解释；黑盒模型从数据学习复杂表示。","帮助选择可解释性与表现的取舍。","手工 gradient descriptor 是白盒，CNN embedding 常视为黑盒。","监管场景可能偏好可解释特征。")
add(W,"图像特征","Image similarity search","相似图片搜索","把查询图和库中图片变成同类向量并搜索近邻。","按视觉内容而非文件名检索。","核心是相同 feature extractor、distance 和 index。","上传鞋子照片找到外观相似商品。")
add(W,"图像处理","Noise reduction","降噪","减少随机像素变化。","让边缘、分割和测量更稳定。","属于 preprocessing，不等于特征提取。","Gaussian blur 降低传感噪声。")
add(W,"图像处理","Morphological operations","形态学操作","按结构元素对二值或灰度形状膨胀、腐蚀等。","去除小噪点、填洞和连接区域。","常作用于 mask。","opening 去除孤立白点。")
add(W,"图像处理","Thresholding","阈值化","按像素值阈值把图像分成类别。","快速生成 binary mask。","全局阈值可能受光照变化影响。","强度 >128 设为前景 1。")
add(W,"元数据","Metadata","元数据","描述数据对象来源、时间、位置、设备、作者等的信息。","用于检索、连接、验证和特征工程。","它可能缺失、被修改或与内容不一致。","照片的拍摄时间与 GPS。")
add(W,"元数据","EXIF","可交换图像文件元数据标准","常保存相机、曝光、拍摄时间和 GPS 等标签。","自动获取数字照片技术信息。","是 metadata 体系之一，不保证所有字段存在。","读取 CreateDate。")
add(W,"元数据","IPTC","新闻与媒体元数据标准","保存标题、作者、版权和关键词等编辑信息。","支持媒体资产管理。","与 EXIF 的设备技术信息侧重点不同。","新闻图片含 caption 与 copyright。")
add(W,"元数据","XMP","可扩展元数据平台","Adobe 发起的可扩展键值元数据格式。","跨文件类型嵌入或伴随描述信息。","可与 EXIF/IPTC 同时存在。","PDF 中保存作者和编辑工具。")
add(W,"元数据","ExifTool","元数据命令行工具","读取、写入并批量导出多种文件元数据。","把 EXIF/IPTC/XMP 自动转为 CSV/JSON 管线输入。","工具输出仍需验证时间、GPS和缺失值。","exiftool -common -csv *.jpg > metadata.csv。")
add(W,"特征工程","Feature engineering","特征工程","把原始数据转换为更能表达预测问题的特征。","提高模型效果、稳定性和可解释性。","包括交互、时间、编码、选择等方法。","由 height、weight 计算 BMI。")
add(W,"特征工程","Feature interaction","特征交互","组合两个或多个特征表达联合效应。","捕捉单个变量无法表示的关系。","可用 product、ratio 等。","房屋面积÷卧室数。")
add(W,"特征工程","Polynomial feature","多项式特征","加入平方、立方或变量乘积等高阶项。","让简单模型拟合非线性关系。","可能迅速增加维度并过拟合。","x²、x1×x2。")
add(W,"特征工程","Lag feature","滞后特征","使用前一个或更早时间点的值作为当前特征。","让模型利用历史依赖进行预测。","只能使用预测时已知的过去值。","用昨天销量预测今天销量。")
add(W,"特征工程","Rolling / Aggregated feature","滚动／聚合特征","在过去固定窗口上计算均值、总和等。","平滑噪声并表达近期趋势。","窗口必须只看过去以防 leakage。","过去 7 天平均温度。")
add(W,"特征工程","One-hot encoding","独热编码","把每个类别变成一个 0/1 列。","让模型使用无自然顺序的类别。","高基数类别会产生高维稀疏矩阵。","颜色 red/blue → 两个二进制列。")
add(W,"特征工程","Target encoding","目标编码","用某类别对应目标值的统计量替代类别。","压缩高基数类别。","必须用训练折或平滑，避免标签泄漏。","用邮编对应训练集平均房价编码邮编。")
add(W,"特征工程","Feature hashing","特征哈希","用哈希把类别映射到固定数量桶。","控制维度并处理新类别。","可能发生 collision。","百万 URL 映射到 2^18 个槽。")
add(W,"特征工程","Feature selection","特征选择","保留有用特征并删除冗余或噪声特征。","降低维度、成本和过拟合风险。","分 filter、wrapper、embedded。","选择与目标相关的 30 个变量。")
add(W,"特征工程","Filter / Wrapper / Embedded methods","过滤／包装／嵌入式选择","分别按统计分数、模型性能搜索、训练过程内置机制选特征。","提供不同计算成本与模型依赖的选择策略。","RFE 是 wrapper；LASSO 可作 embedded。","先用相关系数 filter 删除弱特征。")
add(W,"特征工程","AutoML / FeatureTools","自动机器学习／自动特征工具","自动尝试模型、参数或从关系数据生成候选特征的工具。","减少重复探索并扩大候选空间。","自动化结果仍需防 leakage 和验证业务含义。","FeatureTools 生成客户历史交易聚合。")

# W9 — Stream Data Processing
W="W9"
add(W,"基础","Data stream","数据流","持续到达、随时间变化且潜在无界的 tuple／event 序列。","表示实时交易、日志和传感数据。","与有界 batch dataset 对比。","银行卡交易不断进入反欺诈系统。")
add(W,"基础","Unbounded stream","无界流","没有预先已知终点的数据序列。","说明不能等全部数据到齐才计算。","window 把无界流暂时切成有限 relation。","运行中的温度传感器流。")
add(W,"基础","Event / Record / Message / Tuple","事件／记录／消息／元组","流中的单个原子数据项。","是发布、传输和算子处理的基本单位。","不同平台用词不同，通常都含 payload 和 metadata。","{device:'A',temp:21,ts:'12:00'}。")
add(W,"基础","Data in motion","运动中的数据","数据到达时就被处理，而不是先完整存储。","实现低延迟实时响应。","与传统 DBMS 的 data at rest 对比。","交易到达即评分并决定是否拦截。")
add(W,"基础","Real-time / Near-real-time","实时／近实时","在业务允许的很短延迟内产生结果。","支持告警、推荐和欺诈检测。","实时不必等于零延迟；要看 latency SLA。","异常交易在数百毫秒内告警。")
add(W,"系统","DBMS","数据库管理系统","对持久 relation 执行临时查询和更新。","管理 data at rest 与精确查询结果。","DSMS 则让 continuous query 长期处理 transient stream。","用户提交一次 SELECT 后得到结果。")
add(W,"系统","DSMS (Data Stream Management System)","数据流管理系统","注册持续查询并对不断到来的流增量计算。","处理无界、乱序、高速事件。","把传统 query-over-data 转成 data-through-query。","持续计算最近 5 分钟平均温度。")
add(W,"查询","Continuous query","连续查询","长期运行、随新事件到达不断更新结果的查询。","避免反复手工执行批查询。","是 DSMS 的核心查询模式。","注册“每分钟统计支付失败数”。")
add(W,"架构","Stream processing architecture","流处理架构","把消息摄取层与查询计算层组合的系统设计。","同时解决可靠接收和有明确语义的计算。","Kafka/MQTT 常负责消息；Spark/Flink 负责处理。","producer→Kafka→Flink→sink。")
add(W,"消息","Publish/Subscribe (Pub/Sub)","发布／订阅","publisher 按 topic 发布，subscriber 按 topic 接收，由 broker 解耦双方。","让多个生产者与消费者异步扩展。","不自动等同于 exactly-once 业务语义。","传感器发 temp topic，仪表盘和告警同时订阅。")
add(W,"消息","Publisher / Producer","发布者／生产者","生成并发送消息的组件。","把源事件写入 topic 或 broker。","producer 不需要知道具体 consumer。","mqtt_publisher.py 发送天气记录。")
add(W,"消息","Subscriber / Consumer","订阅者／消费者","接收并处理 topic 中消息的组件。","执行解析、计算或写入下游。","多个 consumer 可独立订阅或组成 consumer group。","告警服务读取温度消息。")
add(W,"消息","Broker","消息代理","接收、路由并按系统能力保存消息的中间服务。","解耦 producer 与 consumer。","MQTT broker 和 Kafka broker 的存储模型不同。","Mosquitto 接收 MQTT publish 并分发。")
add(W,"消息","Topic / Feed","主题／消息流名称","用于分类和路由消息的逻辑通道。","让订阅者只接收关心的数据。","MQTT topic 是层级字符串；Kafka topic 分为 partitions。","building/3/temperature。")
add(W,"MQTT","MQTT","消息队列遥测传输协议","面向 IoT 的轻量级 Pub/Sub 协议。","在网络和设备资源有限时传输传感消息。","它是 messaging protocol，不是复杂 stream processor。","Paho client 向 Mosquitto broker 发布 JSON。")
add(W,"MQTT","Mosquitto","Mosquitto MQTT 代理","Eclipse 提供的开源 MQTT broker。","在本地或服务器上接收和分发 MQTT 消息。","与 Paho client library 配合。","mosquitto 在 1883 端口监听。")
add(W,"MQTT","Paho MQTT","Paho MQTT 客户端库","为 Python 等语言提供 MQTT publish/subscribe API。","编写 publisher、subscriber 和 callback。","Paho 是 client，不是 broker。","client.subscribe('sensor/#')。")
add(W,"MQTT","Callback","回调函数","特定事件发生时由框架自动调用的函数。","异步处理收到的消息或连接事件。","不是普通顺序主动调用。","on_message 中 decode payload 再 json.loads。")
add(W,"MQTT","Payload","消息负载","消息实际携带的数据字节。","承载 JSON、文本或二进制事件内容。","topic 用于路由，payload 用于业务数据。","message.payload.decode('utf-8')。")
add(W,"MQTT","Single-level wildcard +","单层通配符","MQTT 订阅过滤器中匹配恰好一层 topic。","一次订阅多个同层设备或楼层。","+ 不跨越 /；# 匹配后续多层。","home/+/temp 匹配 home/kitchen/temp。")
add(W,"MQTT","Multi-level wildcard #","多层通配符","匹配当前位置之后的所有 topic 层级，通常必须位于末尾。","订阅一个分支下全部消息。","范围比 + 更广。","home/# 匹配 home/kitchen/temp 与 home/door。")
add(W,"MQTT","Retained message","保留消息","broker 为 topic 保存最后一条 retain 消息并立即发给新订阅者。","让新订阅者获得最新状态。","retain 与 QoS 是两个独立设置。","新仪表盘连接后立即得到最后温度。")
add(W,"MQTT","QoS 0 — At most once","服务质量0／至多一次","消息最多交付一次，可能丢失且不重试。","提供最低开销和最低延迟。","适合允许少量丢失的高频遥测。","每秒温度采样偶尔丢一条可接受。")
add(W,"MQTT","QoS 1 — At least once","服务质量1／至少一次","通过确认和重传避免丢失，但可能重复。","适合不能漏消息且 consumer 可去重的场景。","需要 idempotent consumer。","订单事件带 event_id 去重。")
add(W,"MQTT","QoS 2 — Exactly once delivery","服务质量2／协议层恰好一次交付","用更多握手避免协议层重复交付。","在高价值且低吞吐场景提高交付保证。","不单独保证数据库副作用端到端 exactly-once。","支付指令协议传输使用 QoS2。")
add(W,"可靠性","Idempotence","幂等性","相同操作执行多次与执行一次结果相同。","安全处理重试和重复消息。","是 QoS1/at-least-once 管道的关键设计。","按唯一 event_id UPSERT 而非重复 INSERT。")
add(W,"可靠性","Acknowledgement (ACK)","确认消息","接收方通知发送方消息已收到或处理到某阶段。","决定是否重传。","ACK 过早可能在业务写入前崩溃而丢结果。","consumer 成功写库后提交 offset。")
add(W,"Kafka","Apache Kafka","分布式持久化 Pub/Sub 日志平台","高吞吐地保存、复制和重放事件流。","连接多源、多消费者与 stream processor。","比轻量 MQTT 更强调 durable partitioned log。","Web 日志写 Kafka 后由 Spark 与 Flink 分别消费。")
add(W,"Kafka","Partitioned log","分区日志","topic 被拆成多个仅追加、有序的 partition。","通过分区实现并行、扩展和持久重放。","只保证 partition 内顺序，不保证跨 partition 全局顺序。","相同 account_id 作为 key 进入同一 partition。")
add(W,"Kafka","Partition","分区","Kafka topic 的并行和顺序单位。","分散存储与 consumer 工作。","consumer group 内一个 partition 同时分配给一个 consumer。","6 partitions 最多让组内 6 个 consumer 同时有活。")
add(W,"Kafka","Offset","偏移量","record 在 Kafka partition 内的位置编号。","追踪消费进度并支持 replay。","offset 只在所属 partition 内有意义。","consumer 从 offset 120 重新读取。")
add(W,"Kafka","Consumer group","消费者组","多个 consumer 协作分摊同一 topic partitions 的逻辑组。","扩展同一应用的并行消费。","不同 group 各自收到完整流；同组实例分工。","analytics 组与 archive 组各读取所有消息。")
add(W,"Kafka","Replication factor","复制因子","每个 Kafka partition 保留的副本数量。","容忍 broker 故障并提高可用性。","N 个副本理论上可容忍至多 N−1 个副本节点故障，仍取决于 leader/ISR。","replication factor=3。")
add(W,"Kafka","Replay","重放","从旧 offset 再次读取历史消息。","恢复、重算或建立新下游。","依赖 Kafka retention 仍保留数据。","修复 bug 后从昨天 offset 重算。")
add(W,"算子","Stateless operator","无状态算子","每个输出只依赖当前输入事件。","易扩展、恢复和并行。","selection、逐条 projection 常是 stateless。","过滤 length>512。")
add(W,"算子","Stateful operator","有状态算子","输出依赖多个事件或过去信息。","支持聚合、去重、窗口和 join。","需要状态存储、checkpoint 和清理。","计算每个设备最近 10 分钟平均值。")
add(W,"算子","Selection / Projection","选择／投影","selection 按条件筛行；projection 选择或计算字段。","执行逐事件过滤和映射。","在不去重时可逐条无状态处理。","WHERE length>512；SELECT sourceIP,time。")
add(W,"窗口","Window","窗口","从无限流抽取有限 relation 的规则。","为聚合、join 和排序提供有限范围。","可按时间、tuple count、punctuation 或 session 定义。","最近 5 分钟交易。")
add(W,"窗口","Tumbling window","滚动不重叠窗口","固定长度且首尾相接、不重叠的窗口。","每个事件通常只进入一个窗口。","与 sliding window 可重叠不同。","每个整点划分 1 小时统计。")
add(W,"窗口","Sliding window","滑动窗口","具有 window size 和 slide/step，窗口可重叠。","提供连续更新的近期统计。","当 size>slide 时，一个事件可属于多个窗口。","10 分钟窗口每 5 分钟滑动。")
add(W,"窗口","Fixed window","固定窗口","按预定固定时间边界划分的窗口。","周期性汇总。","常对应 tumbling window。","每 1 分钟一个窗口。")
add(W,"窗口","Tuple-count window","计数窗口","按最近 N 条 tuple 而非时间长度取窗口。","处理速率相关的最近事件集合。","相同 timestamp 的 tie 可能导致非确定边界。","最近 100 笔交易。")
add(W,"窗口","Punctuation-based window","标点窗口","由流中显式边界 marker 开始或结束窗口。","处理数据自身定义的可变批次。","既不必是 sliding，也不必是固定 tumbling。","auction_end 标记结束一场拍卖。")
add(W,"窗口","Session window","会话窗口","按同一实体连续活动及 inactivity gap 分组。","捕捉长度可变的用户或设备会话。","边界由活动间隔而非固定时钟决定。","用户 30 分钟无操作则结束 session。")
add(W,"时间语义","Event time","事件时间","事件在源端真实发生的时间。","在乱序到达时仍按业务时间计算正确窗口。","需要 timestamp、watermark 和 late-event 策略。","传感器 12:00 测量、12:05 才上传。")
add(W,"时间语义","Ingestion time","摄取时间","事件进入流处理系统的时间。","在源时间缺失时提供较稳定的入口时间。","包含网络传输延迟，不等于真实发生时间。","Kafka source 12:05 收到事件。")
add(W,"时间语义","Processing time","处理时间","算子实际处理事件时机器的墙钟时间。","实现简单、延迟低。","结果受负载和重试影响，业务时间正确性较弱。","Flink operator 12:05:02 执行。")
add(W,"时间语义","Out-of-order event","乱序事件","事件到达顺序与 event time 顺序不同。","解释为什么需要 event time 与 watermark。","网络、重试和多分区都会造成乱序。","12:02 事件先于 12:01 事件到达。")
add(W,"时间语义","Late event / Allowed lateness","迟到事件／允许迟到量","watermark 越过相关窗口后才到达的事件，以及系统仍接受它的时限。","控制正确性、等待时间和状态成本。","非常晚的数据可丢弃、更新结果或送 side output。","允许迟到 2 分钟后仍更新窗口。")
add(W,"时间语义","Watermark","水位线","系统对 event time 已推进到何处的估计。","触发窗口关闭、输出和状态清理。","不是此前绝无新事件的绝对保证。","watermark=12:10 表示系统认为大部分更早事件已到。")
add(W,"时间语义","WatermarkStrategy","水位线策略","Flink 中从时间戳和迟到假设生成 watermark 的配置。","统一 timestamp 提取、周期水位线和最大乱序量。","策略过激会把正常事件判为 late。","forBoundedOutOfOrderness(Duration.ofSeconds(5))。")
add(W,"连接","Stream-table join / Enrichment","流—表连接／增强","每个流事件查静态或较慢更新的参考表。","补充类别、客户、设备等上下文。","通常比 stream-stream join 状态更可控。","交易流 join 商户风险等级表。")
add(W,"连接","Stream-stream join","流—流连接","在 key 和有限时间范围内匹配两个无界流。","关联同时发生的实时事件。","必须限制时间，否则状态可能无限增长。","点击后 30 分钟内匹配购买。")
add(W,"连接","Join key","连接键","决定两侧记录是否属于同一实体的字段。","缩小 join 候选并分区状态。","相同 key 仍需时间条件控制窗口。","user_id。")
add(W,"连接","Redis lookup","Redis 快速查找","使用内存键值库为事件提供参考数据。","降低 stream-table enrichment 延迟。","缓存可能陈旧，需要刷新策略。","按 product_id 查产品类别。")
add(W,"Spark","Spark Streaming","Spark 的流处理组件","把输入流切成 micro-batch，并用 Spark 引擎处理。","复用 RDD/集群生态做窗口和聚合。","课程材料强调 micro-batching；与 Flink pipelining 对比。","每秒生成一个 RDD 处理 socket 数据。")
add(W,"Spark","Micro-batch","微批","把短时间内到达的事件组成小批次执行。","在批处理引擎上实现流式计算。","仍属于流处理，但延迟通常受 batch interval 限制。","每 1 秒处理一次该秒所有消息。")
add(W,"Spark","DStream (Discretized Stream)","离散流","Spark Streaming 中由一系列连续 RDD 构成的流抽象。","对每个 micro-batch 应用转换。","DStream 的每个时间片底层是 RDD。","lines.flatMap(...).reduceByKeyAndWindow(...)。")
add(W,"Spark","RDD (Resilient Distributed Dataset)","弹性分布式数据集","可分区、不可变、可由 lineage 重建的分布式集合。","提供 Spark 容错和并行计算基础。","DStream 是 RDD 序列；DataFrame 也最终在 Spark 执行引擎上运行。","一个 RDD 保存某秒到达的词。")
add(W,"Flink","Apache Flink","分布式数据流处理框架","以连续 pipelining、状态和 event-time 支持见长。","低延迟处理乱序流、窗口和状态。","Kafka/MQTT 负责消息，Flink 负责计算。","DataStream.keyBy(...).window(...).sum(...)。")
add(W,"Flink","Pipelining","流水线执行","上游生成记录后立即转给可用下游算子。","让不同算子阶段重叠并降低延迟。","与 Spark 经典 stage/micro-batch 边界对比。","map 输出立即进入 reduce。")
add(W,"可靠性","Checkpoint","检查点","周期性保存算子状态与输入位置的一致快照。","失败后恢复 stateful processing。","端到端 exactly-once 还依赖可重放 source 和事务／幂等 sink。","Flink 从 checkpoint 恢复窗口状态和 Kafka offset。")
add(W,"可靠性","Side output","侧输出","把特定事件从主结果流分流到独立流。","保存太晚、异常或解析失败的数据。","比静默丢弃更便于审计。","late events 进入 late-data topic。")
add(W,"性能","Bursty stream / Backpressure","突发流／背压","输入速率突然升高；下游处理不过来时压力向上游传播。","防止无界缓冲并协调速率。","窗口和 watermark 也会受积压影响。","促销开始后消息速率暴增。")

# W10 — Scalable Data Engineering
W="W10"
add(W,"扩展性","Scalability","可扩展性","工作量增长时增加资源仍能维持可接受性能的能力。","评估系统能否持续承载更多数据和用户。","要结合 throughput、latency、成本和效率判断。","数据量十倍后扩容仍能按 SLA 完成。")
add(W,"扩展性","Scale-up (vertical scaling)","纵向扩展","给单机增加 CPU、内存或磁盘。","在架构变化较小时提升单机能力。","受硬件上限和单点故障限制；不要与课程的 scale-up 性能目标混淆。","把服务器从 16 核升级到 64 核。")
add(W,"扩展性","Scale-out (horizontal scaling)","横向扩展","增加更多服务器并把工作分散到集群。","突破单机上限并提高容量。","需要 partitioning、coordination 和 fault tolerance。","从 4 个 worker 扩为 20 个。")
add(W,"扩展性","Speed-up","加速比","固定数据量时，增加资源后运行时间缩短的比例。","衡量并行化效果。","S(p)=T1/Tp；协调和串行部分使其通常低于 p。","100 秒降到 25 秒，speedup=4。")
add(W,"扩展性","Scale-up goal / Size-up","同比扩容目标","数据量和资源同比增加时，运行时间或吞吐表现保持近似不变。","衡量系统处理更大问题的能力。","与固定数据量的 speed-up 不同。","数据×4、节点×4，时间仍约 10 分钟。")
add(W,"性能","Throughput","吞吐量","单位时间内完成的记录、请求或数据量。","衡量系统总处理能力。","高 throughput 不等于单条低 latency。","每秒处理 100,000 events。")
add(W,"性能","Latency / Response time","延迟／响应时间","单个事件或请求从进入到得到结果的时间。","衡量实时性和用户体验。","可能与 throughput 存在权衡。","交易告警 P95 延迟 200 ms。")
add(W,"扩展性","Elasticity","弹性","资源随负载变化自动增加或减少的能力。","在满足性能时控制成本。","scalability 是能否扩展，elasticity 强调动态自动调整。","白天自动加 worker，夜间缩容。")
add(W,"架构","Scale-agnostic","规模无关设计","应用逻辑尽量不依赖具体节点数和数据位置。","让底层扩容而无需改业务代码。","由 sharding、replication 和分布式框架隐藏复杂性。","同一 Spark 程序从本地切到集群。")
add(W,"架构","Loosely coupled system","松耦合系统","组件通过稳定接口交互，彼此依赖较少。","支持独立扩容、替换和故障隔离。","消息队列常用于解耦。","采集服务与分析服务通过 Kafka 连接。")
add(W,"架构","Separation of compute and storage","计算存储分离","计算节点与持久存储独立扩缩。","按不同需求调整算力和容量。","会增加网络依赖和 availability 考量。","Spark 临时集群读取 S3 数据。")
add(W,"存储","Indexing","索引","创建辅助结构以更快定位满足条件的数据。","减少全表扫描。","提高读性能但占空间并增加写维护成本。","B-tree 加速 customer_id 查询。")
add(W,"存储","Clustering","数据聚簇／物理排序","按某些键让相近记录物理靠近。","减少范围查询 I/O。","与 ML clustering 无关；这里是存储布局。","按日期聚簇日志。")
add(W,"存储","RAID","独立磁盘冗余阵列","把数据条带化或复制到多块磁盘。","提高单机存储吞吐或容错。","不是跨机器数据库 replication 的替代。","RAID 1 镜像两个磁盘。")
add(W,"存储","Row store","行式存储","同一记录的各列连续存放。","适合整行点查、插入和 OLTP。","列式存储更适合扫描少数列的分析。","读取某客户完整资料。")
add(W,"存储","Column store / Columnar storage","列式存储","同一列的值连续存放。","减少分析查询 I/O、提高压缩和列向量计算。","不要与 wide-column database 混淆。","十亿行只读取 sales 列求 AVG。")
add(W,"存储","Pure vs Mixed column organisation","纯列／混合列组织","页面只存一种列值，或在页面中混合若干列块。","在扫描效率与重建行成本间取舍。","都是 column-store 的物理布局选择。","同一 page 只存 amount 列。")
add(W,"存储","Apache Parquet","Parquet 列式文件","支持嵌套类型、压缩和编码的开源列式文件格式。","高效保存数据湖分析数据。","是文件格式，不是数据库或 wide-column store。","Spark 只读取 Parquet 的 date、amount 两列。")
add(W,"存储","Compression / Encoding","压缩／编码","利用重复值和数据规律减少存储与 I/O。","列式同类型数据通常更易压缩。","节省 I/O 可能比解压 CPU 成本更重要。","状态列用字典编码。")
add(W,"存储","Wide-column store","宽列数据库","按 row key、column family 和稀疏列组织的分布式数据库模型。","存储超宽、稀疏且可扩展的记录。","不同于按列连续存放的 columnar analytics format。","HBase / Bigtable。")
add(W,"存储","Column family","列族","wide-column store 中一起组织和存储的一组相关列。","定义物理局部性和访问单位。","列族内部通常按行键组织。","profile:name 与 profile:email 同属 profile family。")
add(W,"分布式数据","Data partitioning / Sharding","数据分区／分片","把原数据的不同子集放到不同磁盘或节点。","提高容量和并行度。","partition 保存不同数据；replica 保存相同数据副本。","按 customer_id 把客户分到 8 个 shards。")
add(W,"分布式数据","Horizontal partitioning","水平分区","按行把表拆成多个 shard。","让每个节点处理部分记录。","所有分区通常保留相同列。","NSW 行与 VIC 行存不同节点。")
add(W,"分布式数据","Vertical partitioning","垂直分区","按列把表拆分并用 key 关联。","分离常用列、敏感列或大对象。","各分区保存不同属性。","基本资料与大照片列分开。")
add(W,"分布式数据","Round-robin partitioning","轮询分区","依次把记录分配到各节点。","在无好 key 时获得较均匀记录数。","不保留范围局部性，按业务 key 查询可能扫全部节点。","第 1 行到节点1、第2行到节点2。")
add(W,"分布式数据","Hash partitioning","哈希分区","对 key 做 hash 决定目标分区。","通常获得均匀分布和等值查询定位。","不利于范围查询。","hash(customer_id)%8。")
add(W,"分布式数据","Range partitioning","范围分区","按 key 值区间分配节点。","支持范围查询和顺序扫描。","容易因热点区间产生 skew。","日期 1–7 日、8–14 日分别存储。")
add(W,"分布式数据","Partition key / Shard key","分区键／分片键","决定记录存到哪个分区的字段。","影响负载均衡、查询路由和 join 成本。","好 key 高基数、分布均匀且匹配访问模式。","customer_id 比 state 更可能均匀。")
add(W,"分布式数据","Data skew / Hotspot","数据倾斜／热点","少数 partition 拥有过多数据或请求。","解释为何增加节点仍可能慢。","坏 partition key 或流行 key 常导致 skew。","50% 订单都属于同一 merchant_id。")
add(W,"分布式数据","Shuffle","重分区传输","为 group/join 等按 key 在节点间重新移动数据。","把相同 key 聚到一起。","网络和磁盘成本高，常是瓶颈。","groupBy(customer_id) 前跨节点发送记录。")
add(W,"复制","Data replication","数据复制","在不同位置保存相同数据的多个副本。","提高可用性、读取能力和故障恢复。","不是 backup；错误也可能被复制。","一个 partition 有 3 个 replicas。")
add(W,"复制","Synchronous / Eager replication","同步／急切复制","原事务提交前更新所需副本。","提供更强一致性。","等待多个节点导致更高写延迟和可用性风险。","两个副本确认后才返回成功。")
add(W,"复制","Asynchronous / Lazy replication","异步／延迟复制","先在一个副本提交，之后传播到其他副本。","降低写延迟并提高吞吐。","secondary 可能 stale，故障时可能丢最后更新。","primary 返回后再 log shipping。")
add(W,"复制","Primary copy / Single leader","主副本／单领导者","所有写入先到唯一 authoritative leader。","简化写入排序和冲突控制。","读取可从 follower，但可能旧。","MongoDB Primary 接收全部 writes。")
add(W,"复制","Multi-leader / Update anywhere","多领导者／任意处更新","多个副本都能接受写入。","支持多地区本地写和灵活性。","并发冲突需要检测与 resolution。","悉尼和伦敦 leader 同时修改记录。")
add(W,"复制","Log shipping","日志传送","把 leader 的变更日志发送给 replicas 重放。","实现异步复制。","传的是变化记录而非每次完整数据集。","MongoDB secondary 应用 oplog。")
add(W,"复制","Conflict resolution","冲突解决","合并多个 leader 对同一数据的并发修改。","保证副本最终收敛。","策略可按版本、时间、业务规则或人工处理。","两个地区同时改用户名时选择版本。")
add(W,"MongoDB","MongoDB sharding","MongoDB 分片","把 collection 按 shard key 分布到多个 shards。","水平扩展容量和吞吐。","每个 shard 通常又是 replica set。","orders collection 按 customer_id 分片。")
add(W,"MongoDB","mongos","MongoDB 查询路由器","根据 shard metadata 把客户端请求路由到目标 shards。","隐藏数据分布并合并结果。","缺少 shard key 可能 scatter-gather。","包含 customer_id 的查询只访问一个 shard。")
add(W,"MongoDB","Config server","配置服务器","保存 MongoDB sharded cluster 的分片元数据。","让 mongos 知道 chunk 位于哪里。","不保存主要业务 collection 数据。","记录 key range→shard 映射。")
add(W,"MongoDB","Shard / Replica set","分片／副本集","shard 保存数据子集；replica set 保存该子集的多个副本。","同时实现容量扩展和可用性。","sharding 与 replication 是正交机制。","Shard A 是三节点 replica set。")
add(W,"MongoDB","Read Preference","读取偏好","控制 MongoDB 读请求发往 primary 还是 secondary。","在一致性、延迟和读扩展间取舍。","读 secondary 可能看到 stale data。","primaryPreferred。")
add(W,"MongoDB","Scatter-gather","广播查询","路由器把查询发到多个或全部 shards 再合并。","处理无法按 shard key 定向的查询。","成本高，良好查询应尽量 targeted。","不带 customer_id 的过滤扫所有 shards。")
add(W,"一致性","Strong consistency","强一致性","读操作返回最近成功写入的值。","为金融等场景提供单一最新视图。","网络分区下常以降低 availability 为代价。","转账后任何节点立即读到新余额。")
add(W,"一致性","High availability","高可用性","系统在故障时仍能响应请求。","减少服务中断。","响应不一定是最新值。","一个节点宕机仍由 replica 提供读服务。")
add(W,"一致性","Partition tolerance","分区容错","网络分裂、节点互不可达时系统仍能按选定策略运行。","是分布式系统必须面对的故障条件。","CAP 中 P 不是平时可随意关闭的功能。","两机房断网。")
add(W,"一致性","CAP theorem","CAP 定理","发生网络分区时，系统不能同时保证强一致响应与所有请求可用。","帮助解释分区故障时的设计取舍。","讨论的是 C/A 在 P 下的选择，不是日常任意选两个。","银行偏 CP，社交计数可偏 AP。")
add(W,"一致性","CP system","一致性＋分区容错系统","分区时拒绝或延迟部分请求以避免返回不一致数据。","保护关键正确性。","牺牲部分 availability。","无法确认最新余额时拒绝转账。")
add(W,"一致性","AP system","可用性＋分区容错系统","分区时继续响应，即使数据暂时不一致。","保持服务可用。","之后需要副本收敛。","点赞数暂时不同但仍可点赞。")
add(W,"一致性","Read-your-writes consistency","读己之写一致性","用户写入后自己的后续读取至少能看到该写入。","保证直观会话体验。","异步 replica 读可能违反它。","换头像后刷新应立即看到新头像。")
add(W,"一致性","Stale read","陈旧读取","从未追上最新写入的副本读到旧值。","识别异步复制的一致性风险。","通过读 primary、等待或 session guarantee 缓解。","伦敦 replica 尚未收到纽约头像更新。")
add(W,"存储系统","HDFS","Hadoop 分布式文件系统","把大文件切成 blocks 并在 DataNodes 间复制的分布式文件系统。","为大规模顺序读写与计算提供可靠存储。","NameNode 管 metadata，DataNode 存实际 blocks。","Spark 从 HDFS 读取日志。")
add(W,"存储系统","NameNode","名称节点","管理 HDFS namespace、权限、block 位置和复制信息。","告诉 client 数据块在哪。","普通读取中不转发全部文件数据。","client 先向 NameNode 请求 block locations。")
add(W,"存储系统","DataNode","数据节点","实际存储和传输 HDFS blocks 的 worker。","向 client 提供数据并复制 blocks。","由 NameNode 管理元数据。","client 从最近 DataNode 读取 block。")
add(W,"存储系统","Block","数据块","HDFS 将大文件切分的固定大粒度存储单位。","允许分布、复制和并行读取。","小文件过多会增加 NameNode metadata 压力。","一个 256MB 文件分成多个 blocks。")
add(W,"存储系统","Data locality","数据局部性","尽量让计算在数据所在或邻近节点执行。","减少网络传输并提高吞吐。","计算存储分离时要权衡远程 I/O。","调度 map task 到保存 block 的 DataNode。")
add(W,"生态","Hadoop","Hadoop 生态／MapReduce 实现","包含 HDFS、YARN 和 MapReduce 等分布式组件。","隐藏并行化、容错和数据分布细节。","Spark/Flink 可运行在 Hadoop 存储与资源层上。","HDFS 存数据，YARN 调度作业。")
add(W,"生态","YARN","Yet Another Resource Negotiator","Hadoop 集群资源管理和作业调度层。","给 Spark/Flink 等应用分配容器资源。","不是存储系统，也不是查询语言。","Spark application 提交到 YARN。")
add(W,"生态","Apache Hive / HiveQL","Hive／Hive 查询语言","在 HDFS 文件上定义关系 schema 并用 SQL 风格查询。","把高层查询翻译为分布式作业。","schema-on-read，早期常转 MapReduce。","HiveQL GROUP BY 统计词频。")
add(W,"计算模型","MapReduce","映射归约模型","用 map 产生 key-value，再经 shuffle/sort 送给 reduce 汇总。","在集群上并行处理大数据。","框架负责分区、调度和容错。","WordCount。")
add(W,"计算模型","Map","映射阶段","对输入记录独立转换并发出中间 key-value。","过滤、解析和建立分组键。","通常高度并行。","每个单词输出 (word,1)。")
add(W,"计算模型","Reduce","归约阶段","接收同 key 的所有值并计算汇总。","完成 count、sum 等按键聚合。","依赖前面的 shuffle/sort。","对 (word,[1,1,1]) 输出 3。")
add(W,"计算模型","Combiner","本地合并器","在 map 端先局部合并中间结果。","减少 shuffle 数据量。","只能用于可安全结合的运算；平均值不能直接平均局部平均。","局部先求 word count。")
add(W,"Spark","Apache Spark","分布式数据处理框架","以内存计算和高层 API 为主的分布式数据处理框架。","执行批处理、SQL、ML 和流处理。","以 RDD 为核心并提供 DataFrame/SQL。","PySpark 聚合 Bitcoin 数据。")
add(W,"Spark","SparkSession","Spark 应用入口对象","负责配置、读写数据和访问 SQL 功能。","统一建立 DataFrame 和执行环境。","本地 local[*] 与集群模式可使用相同 API。","SparkSession.builder.appName(...).getOrCreate()。")
add(W,"Spark","Driver","驱动进程","运行主程序、构建计划并协调 executors。","调度 jobs、stages 和 tasks。","collect() 把数据拉回 driver，可能 OOM。","Notebook Python 进程常是 driver。")
add(W,"Spark","Executor","执行器进程","在 worker 上执行 tasks 并缓存 partitions。","完成分布式计算。","executor 数与 partition 数共同影响并行度。","每个 executor 处理若干 DataFrame partitions。")
add(W,"Spark","RDD","弹性分布式数据集","不可变、可分区、可由 lineage 重建的集合。","提供 Spark 核心容错抽象。","DataFrame 是更高层结构化 API。","textFile(...).flatMap(...)。")
add(W,"Spark","DataFrame","带命名列的数据集","具有 schema，并用高层关系操作表达计算。","让 Catalyst 优化查询并自动并行。","比手写 RDD 更适合结构化数据。","df.groupBy('year').avg('volume')。")
add(W,"Spark","Dataset API","类型化数据集 API","结合对象类型安全与 Spark 优化的高层 API。","在 Scala/Java 中提供编译期类型帮助。","Python 主要使用 DataFrame，不提供同样的 typed Dataset。","Dataset[Person]。")
add(W,"Spark","Transformation","转换操作","返回新 RDD/DataFrame 的惰性操作。","构建执行 DAG。","不会立即运行，直到 action 触发。","select、filter、groupBy。")
add(W,"Spark","Action","动作操作","要求结果或写出数据并触发执行。","启动 Spark job。","collect/show/count/write 都会执行计划。","df.count()。")
add(W,"Spark","Lazy evaluation","惰性求值","先记录 transformations，遇到 action 才真正执行。","让优化器重排、合并操作并减少工作。","看到代码调用 filter 不代表已经扫描数据。","df.filter(...).select(...); df.show() 时运行。")
add(W,"Spark","DAG","有向无环图","表示 transformations 依赖关系的执行计划图。","帮助切分 stages、调度和容错。","wide dependency 常形成 stage 边界。","Spark UI 显示 job DAG。")
add(W,"Spark","Narrow vs Wide dependency","窄依赖／宽依赖","窄依赖的子 partition 只依赖少量父 partition；宽依赖跨多分区取数。","判断是否可流水线及是否发生 shuffle。","map/filter 通常窄；groupByKey 通常宽。","reduceByKey 会触发按 key 重分区。")
add(W,"Spark","Cache / Persist","缓存／持久化中间结果","把重复使用的分布式数据保留在内存或磁盘。","避免反复计算 lineage。","缓存也占资源，且第一次 action 才物化。","df.cache(); df.count()。")
add(W,"Spark","collect() / toPandas()","收集到驱动端","把分布式结果全部复制到 driver 内存。","只适合小结果的本地查看或绘图。","对大数据使用会造成 driver OOM。","先 groupBy 聚合成 12 行再 toPandas。")
add(W,"Spark","Temporary view","临时视图","把 DataFrame 注册为当前 SparkSession 内可用的 SQL 名称。","让 DataFrame 与 spark.sql 互操作。","会话结束后不持久保存。","createOrReplaceTempView('bitcoin')。")
add(W,"Spark","Catalyst Optimizer","Catalyst 查询优化器","Spark SQL 把表达式转换并优化 logical/physical plan 的框架。","执行谓词下推、列裁剪等优化。","依赖结构化 DataFrame/SQL 信息。","explain() 查看优化计划。")
add(W,"Spark","Cost-Based Optimizer (CBO)","基于成本优化器","利用统计信息估算候选计划成本。","选择 join 顺序和策略。","统计信息陈旧会降低选择质量。","选择 broadcast join 或 sort-merge join。")
add(W,"Spark","Adaptive Query Execution (AQE)","自适应查询执行","运行时根据实际数据统计调整物理计划。","处理估算误差、shuffle partition 和 skew。","是在执行阶段动态优化。","运行时合并过小 shuffle partitions。")
add(W,"Spark","UDF (User-Defined Function)","用户自定义函数","用户编写并在数据操作中调用的函数。","表达内建函数没有的业务逻辑。","可能阻碍优化并有序列化开销，优先内建函数。","自定义文本评分函数。")
add(W,"Spark","local[*]","本地全核模式","在单个 JVM/电脑上用所有本地 CPU 核运行 Spark。","验证 API、逻辑和 notebook。","不代表真实多节点，也不能证明网络扩展性。","SparkSession.master('local[*]')。")
add(W,"Flink","Flink DataSet API","Flink 批数据 API","对有界集合执行批处理转换的 API。","表达批量 join、group 和 iteration。","课程中与 DataStream API 区分。","env.from_collection(...).group_by(...)。")
add(W,"Flink","Flink DataStream API","Flink 流数据 API","对有界或无界事件流执行状态、窗口和 event-time 操作。","实现原生连续流处理。","位于 Flink runtime 之上。","stream.key_by(...).window(...)。")
add(W,"Flink","Table API / SQL","Flink 表 API／SQL","在流和批数据上使用关系表达式。","让优化器生成 dataflow plan。","动态表可表达持续更新结果。","SELECT key,COUNT(*) FROM stream GROUP BY key。")
add(W,"Flink","env.execute()","Flink 执行触发","提交并启动此前构建的执行计划。","把 lazy plan 变成运行中的 job。","某些 print/collect 调用也可能立即触发。","定义 pipeline 后调用 env.execute()。")

